use rhwp::DocumentCore;
use rhwp::model::control::Control;
use serde_json::{json,Value};
use std::path::PathBuf;

fn blank()->DocumentCore{let mut d=DocumentCore::new_empty();d.create_blank_document_native().unwrap();d}
fn create(d:&mut DocumentCore,kind:&str)->(usize,usize){let r:Value=serde_json::from_str(&d.create_shape_control_native(0,0,0,9000,4000,0,0,true,"Square",kind,false,false,&[]).unwrap()).unwrap();(r["paraIdx"].as_u64().unwrap()as usize,r["controlIdx"].as_u64().unwrap()as usize)}
fn numbers(d:&DocumentCore)->Vec<u16>{d.document().sections.iter().flat_map(|s|s.paragraphs.iter()).flat_map(|p|p.controls.iter()).filter_map(|c|match c{Control::Shape(s)=>s.drawing().and_then(|d|d.caption.as_ref()),_=>None}).flat_map(|c|c.paragraphs.iter()).flat_map(|p|p.controls.iter()).filter_map(|c|match c{Control::AutoNumber(a)=>Some(a.assigned_number),_=>None}).collect()}
fn state(d:&DocumentCore)->Value{json!((0..d.page_count()).map(|p|json!({"page":p,"controls":serde_json::from_str::<Value>(&d.get_page_control_layout_native(p).unwrap()).unwrap(),"text":serde_json::from_str::<Value>(&d.get_page_text_layout_native(p).unwrap()).unwrap()})).collect::<Vec<_>>())}
fn difference(a:&Value,b:&Value,p:&str,out:&mut Vec<Value>){match(a,b){(Value::Number(a),Value::Number(b))=>{let(x,y)=(a.as_f64().unwrap(),b.as_f64().unwrap());if !x.is_finite()||!y.is_finite()||(x-y).abs()>0.2{out.push(json!({"path":p,"before":a,"after":b}));}},(Value::Array(a),Value::Array(b))=>{if a.len()!=b.len(){out.push(json!({"path":format!("{p}.length"),"before":a.len(),"after":b.len()}));}for i in 0..a.len().max(b.len()){difference(a.get(i).unwrap_or(&Value::Null),b.get(i).unwrap_or(&Value::Null),&format!("{p}/{i}"),out);}},(Value::Object(a),Value::Object(b))=>{let keys:std::collections::BTreeSet<_>=a.keys().chain(b.keys()).collect();for k in keys{difference(a.get(k).unwrap_or(&Value::Null),b.get(k).unwrap_or(&Value::Null),&format!("{p}/{k}"),out);}},_=>if a!=b{out.push(json!({"path":p,"before":a,"after":b}));}}}
fn model(d:&DocumentCore)->Vec<u8>{serde_json::to_vec(&d.document().sections.iter().map(|s|&s.paragraphs).collect::<Vec<_>>()).unwrap()}
fn equal(a:&Value,b:&Value){let mut diff=vec![];difference(a,b,"$",&mut diff);assert!(diff.is_empty(),"full geometry mismatch {:?}",diff.iter().take(5).collect::<Vec<_>>());}
fn cycles(d:&DocumentCore,label:&str){let root=PathBuf::from(std::env::var("JUEONY_REPO").unwrap());let out=root.join("build/caption-closure77");let before=state(d);let raw=model(d);let metadata:Value=serde_json::from_str(&d.get_document_metadata_native()).unwrap();let mut results=vec![];
 for format in ["hwp","hwpx"]{let mut current=None;for index in 1..=2{let source=current.as_ref().unwrap_or(d);let r=if format=="hwp"{source.export_hwp_with_adapter_snapshot_with_report().unwrap()}else{source.export_hwpx_native_with_report().unwrap()};assert!(r.content_loss().is_empty(),"genuine loss {}",r.content_loss().to_json());let b=r.into_bytes();let reopened=DocumentCore::from_bytes(&b).unwrap();let mut delta=vec![];difference(&before,&state(&reopened),"$",&mut delta);let m:Value=serde_json::from_str(&reopened.get_document_metadata_native()).unwrap();let unchanged=raw==model(d);let values_equal=metadata["values"]==m["values"];let artifact=format!("{label}-{index}.{format}");std::fs::write(out.join(&artifact),b).unwrap();results.push(json!({"format":format,"cycle":index,"artifact":artifact,"geometryDifferences":delta.len(),"firstDifferences":delta.iter().take(5).collect::<Vec<_>>(),"metadata5Equal":values_equal,"sourceUnchanged":unchanged}));std::fs::write(out.join(format!("{label}-result.json")),serde_json::to_vec_pretty(&results).unwrap()).unwrap();assert!(delta.is_empty()&&values_equal&&unchanged,"strict save failed: {:?}",results.last());current=Some(reopened);}}
}
#[test]fn attach_caption_assigns_one_before_any_property_or_export(){let mut d=blank();let(p,c)=create(&mut d,"rectangle");let warm=state(&d);d.attach_caption_at(p,c).unwrap();assert_eq!(numbers(&d),vec![1]);let live=state(&d);assert_ne!(live,warm,"attach must invalidate the already-read page tree");assert!(live.to_string().contains("그림 1"));assert!(!live.to_string().contains("그림 0"));cycles(&d,"attach-immediate");}
#[test]fn exact_parent_hide_and_caption_properties_reproduction(){let mut d=blank();d.set_page_hide_native(0,0,true,false,false,false,false,true).unwrap();let(p,c)=create(&mut d,"rectangle");d.attach_caption_at(p,c).unwrap();d.set_shape_properties_native(0,p,c,r#"{"captionDirection":"Top","captionVertAlign":"Center","captionSpacing":850,"captionWidth":8504}"#).unwrap();assert_eq!(numbers(&d),vec![1]);cycles(&d,"parent-reproduction");}
#[test]fn real_caption_properties_and_ellipse_preserve_layout(){let mut d=blank();let(p,c)=create(&mut d,"ellipse");d.attach_caption_at(p,c).unwrap();d.set_shape_properties_native(0,p,c,r#"{"hasCaption":true,"captionDirection":"Top","captionVertAlign":"Center","captionSpacing":850,"captionWidth":8504}"#).unwrap();let props:Value=serde_json::from_str(&d.get_shape_properties_native(0,p,c).unwrap()).unwrap();assert_eq!(props["captionDirection"],"Top");assert_eq!(props["captionVertAlign"],"Center");cycles(&d,"ellipse-real-properties");}
#[test]fn detach_renumbers_remaining_live_caption_and_reopens(){let mut d=blank();let(p,c)=create(&mut d,"rectangle");d.attach_caption_at(p,c).unwrap();let(p2,c2)=create(&mut d,"ellipse");d.attach_caption_at(p2,c2).unwrap();assert_eq!(numbers(&d),vec![1,2]);let _=state(&d);d.detach_caption_at(p,c).unwrap();assert_eq!(numbers(&d),vec![1]);cycles(&d,"detach-renumber");}
#[test]fn duplicate_attach_and_absent_detach_are_true_noops(){let mut d=blank();let(p,c)=create(&mut d,"rectangle");d.attach_caption_at(p,c).unwrap();let before=model(&d);let geometry=state(&d);let result:Value=serde_json::from_str(&d.attach_caption_at(p,c).unwrap()).unwrap();assert_eq!(result["ok"],false);assert_eq!(model(&d),before);equal(&geometry,&state(&d));d.detach_caption_at(p,c).unwrap();let before=model(&d);let geometry=state(&d);let result:Value=serde_json::from_str(&d.detach_caption_at(p,c).unwrap()).unwrap();assert_eq!(result["ok"],false);assert_eq!(model(&d),before);equal(&geometry,&state(&d));}
#[test]fn invalid_owner_does_not_mutate_body_or_assign_any_numbers(){let mut d=blank();let(p,_)=create(&mut d,"rectangle");let before=model(&d);let geometry=state(&d);let result:Value=serde_json::from_str(&d.attach_caption_at(p,usize::MAX).unwrap()).unwrap();assert_eq!(result["ok"],false);assert_eq!(model(&d),before);equal(&geometry,&state(&d));}
#[test]fn attach_detach_snapshot_history_preserves_exact_layout(){let mut d=blank();let(p,c)=create(&mut d,"rectangle");let before=state(&d);let undo=d.save_snapshot_native();d.attach_caption_at(p,c).unwrap();let attached=state(&d);let redo=d.save_snapshot_native();d.restore_snapshot_native(undo).unwrap();equal(&before,&state(&d));d.restore_snapshot_native(redo).unwrap();equal(&attached,&state(&d));cycles(&d,"history-attached");let attached_undo=d.save_snapshot_native();d.detach_caption_at(p,c).unwrap();let detached=state(&d);let detached_redo=d.save_snapshot_native();d.restore_snapshot_native(attached_undo).unwrap();equal(&attached,&state(&d));d.restore_snapshot_native(detached_redo).unwrap();equal(&detached,&state(&d));cycles(&d,"history-detached");}
#[test]fn explicit_picture_start_is_respected_instead_of_hardcoded_one(){let mut d=blank();let mut doc=d.document().clone();doc.doc_properties.picture_start_num=7;doc.doc_properties.raw_data=None;doc.sections[0].section_def.picture_num=7;for p in &mut doc.sections[0].paragraphs{for c in &mut p.controls{if let Control::SectionDef(sd)=c{sd.picture_num=7;}}}d.set_document(doc);let(p,c)=create(&mut d,"rectangle");d.attach_caption_at(p,c).unwrap();assert_eq!(numbers(&d),vec![7]);assert!(state(&d).to_string().contains("그림 7"));cycles(&d,"explicit-start-seven");}

fn caption_ir(d:&DocumentCore,p:usize,c:usize)->Value{let Control::Shape(s)=&d.document().sections[0].paragraphs[p].controls[c]else{panic!("shape expected")};serde_json::to_value(&s.drawing().unwrap().caption).unwrap()}
#[test]fn existing_caption_accepts_direction_only_partial_update(){let mut d=blank();let(p,c)=create(&mut d,"rectangle");d.attach_caption_at(p,c).unwrap();d.set_shape_properties_native(0,p,c,r#"{"captionDirection":"Top","captionVertAlign":"Center","captionSpacing":850,"captionWidth":8504}"#).unwrap();let props:Value=serde_json::from_str(&d.get_shape_properties_native(0,p,c).unwrap()).unwrap();assert_eq!(props["hasCaption"],true);assert_eq!(props["captionDirection"],"Top");assert_eq!(props["captionVertAlign"],"Center");assert_eq!(props["captionSpacing"],850);assert_eq!(props["captionWidth"],8504);assert_eq!(numbers(&d),vec![1]);cycles(&d,"direction-only-partial");}
#[test]fn partial_caption_keys_cannot_create_caption_and_unrelated_keys_do_not_mutate_it(){let mut d=blank();let(p,c)=create(&mut d,"rectangle");d.set_shape_properties_native(0,p,c,r#"{"captionDirection":"Top","captionSpacing":850}"#).unwrap();let props:Value=serde_json::from_str(&d.get_shape_properties_native(0,p,c).unwrap()).unwrap();assert_eq!(props["hasCaption"],false);assert!(numbers(&d).is_empty());assert_eq!(caption_ir(&d,p,c),Value::Null);d.attach_caption_at(p,c).unwrap();let original=caption_ir(&d,p,c);d.set_shape_properties_native(0,p,c,r#"{"width":9100}"#).unwrap();assert_eq!(caption_ir(&d,p,c),original,"unrelated resize must not mutate caption content or formatting");assert_eq!(numbers(&d),vec![1]);cycles(&d,"unrelated-shape-key");}
